<script setup>import {state,actions} from '../../domain/prototypeStore.js'</script>
<template><section class="page-stack"><div class="page-heading"><div class="module-icon">值</div><div><h2>人员与值班</h2><p>查看应急职责、联系状态和当前值班安排</p></div></div><article class="panel"><h3>当前值班</h3><div class="button-row"><button v-for="p in state.people" :key="p.id" class="secondary-button" @click="p.duty=!p.duty;actions.switchRole(state.user.role)">{{p.duty?'取消值班':'安排值班'}} · {{p.name}}</button></div></article><div class="table-card"><table><thead><tr><th>姓名</th><th>应急职责</th><th>所属小组</th><th>联系状态</th><th>值班</th></tr></thead><tbody><tr v-for="p in state.people" :key="p.id"><td>{{p.name}}</td><td>{{p.role}}</td><td>{{p.group}}</td><td>{{p.contact}}</td><td>{{p.duty?'当前值班':'—'}}</td></tr></tbody></table></div></section></template>
